static float s_distance[LSTM_INFERENCE_WINDOW_SIZE];
static float s_delta[LSTM_INFERENCE_WINDOW_SIZE];
static uint8_t s_sample_count;
static bool s_has_last_sample;
static uint32_t s_last_sequence;
static int64_t s_last_monotonic_us;
static float s_threshold_m = (float)CONFIG_HRC_LSTM_THRESHOLD_MM / 1000.0f;
static lstm_inference_result_t s_latest;

static void lstm_clear_window(void)
{
    memset(s_distance, 0, sizeof(s_distance));
    memset(s_delta, 0, sizeof(s_delta));
    s_sample_count = 0;
    s_has_last_sample = false;
    s_last_sequence = 0;
    s_last_monotonic_us = 0;
}

static void lstm_clear_forecast(void)
{
    memset(s_latest.distance_m, 0, sizeof(s_latest.distance_m));
    s_latest.has_predicted_violation = false;
    s_latest.predicted_violation_ms = 0;
    s_latest.early_warning = false;
}

static float lstm_sigmoid(float value)
{
    if (value >= 0.0f)
    {
        const float e = expf(-value);
        return 1.0f / (1.0f + e);
    }
    const float e = expf(value);
    return e / (1.0f + e);
}

static bool lstm_is_contiguous(uint32_t sequence, int64_t monotonic_us)
{
    if (!s_has_last_sample || sequence != s_last_sequence + 1u)
    {
        return false;
    }

    const int64_t dt_us = monotonic_us - s_last_monotonic_us;
    const int64_t expected_us = (int64_t)CONFIG_HRC_SAMPLE_PERIOD_MS * 1000LL;
    const int64_t deviation_us = dt_us - expected_us;
    return dt_us > 0 && dt_us <= HRC_LSTM_MAX_GAP_US &&
           deviation_us <= HRC_LSTM_TIME_JITTER_US &&
           deviation_us >= -HRC_LSTM_TIME_JITTER_US;
}

static void lstm_shift_and_append(float distance_m, float delta_m)
{
    if (s_sample_count == LSTM_INFERENCE_WINDOW_SIZE)
    {
        for (size_t i = 1; i < LSTM_INFERENCE_WINDOW_SIZE; ++i)
        {
            s_distance[i - 1] = s_distance[i];
            s_delta[i - 1] = s_delta[i];
        }
        s_sample_count = LSTM_INFERENCE_WINDOW_SIZE - 1u;
    }

    s_distance[s_sample_count] = distance_m;
    s_delta[s_sample_count] = delta_m;
    ++s_sample_count;
}

static bool lstm_run_model(void)
{
    float input[LSTM_INFERENCE_WINDOW_SIZE][2];
    float hidden[HRC_LSTM_UNITS] = {0.0f};
    float cell[HRC_LSTM_UNITS] = {0.0f};
    float gates[HRC_LSTM_GATES];
    float dense[HRC_LSTM_UNITS];

    for (size_t timestep = 0; timestep < LSTM_INFERENCE_WINDOW_SIZE; ++timestep)
    {
        /* Contract pp-lstm-v1: delta[0] is zero for every sliding window. */
        const float delta_m = timestep == 0u ? 0.0f : s_delta[timestep];
        input[timestep][0] = (s_distance[timestep] - s_distance_mean) / s_distance_std;
        input[timestep][1] = (delta_m - s_delta_mean) / s_delta_std;
        if (!isfinite(input[timestep][0]) || !isfinite(input[timestep][1]))
        {
            return false;
        }

        for (size_t gate = 0; gate < HRC_LSTM_GATES; ++gate)
        {
            float value = s_lstm_bias[gate];
            value += input[timestep][0] * s_lstm_kernel[0][gate];
            value += input[timestep][1] * s_lstm_kernel[1][gate];
            for (size_t unit = 0; unit < HRC_LSTM_UNITS; ++unit)
            {
                value += hidden[unit] * s_lstm_recurrent_kernel[unit][gate];
            }
            gates[gate] = value;
        }

        for (size_t unit = 0; unit < HRC_LSTM_UNITS; ++unit)
        {
            const float i = lstm_sigmoid(gates[unit]);
            const float f = lstm_sigmoid(gates[HRC_LSTM_UNITS + unit]);
            const float candidate = tanhf(gates[(HRC_LSTM_UNITS * 2u) + unit]);
            const float o = lstm_sigmoid(gates[(HRC_LSTM_UNITS * 3u) + unit]);
            cell[unit] = f * cell[unit] + i * candidate;
            hidden[unit] = o * tanhf(cell[unit]);
        }
    }

    for (size_t unit = 0; unit < HRC_LSTM_UNITS; ++unit)
    {
        float value = s_dense_bias[unit];
        for (size_t input_unit = 0; input_unit < HRC_LSTM_UNITS; ++input_unit)
        {
            value += hidden[input_unit] * s_dense_kernel[input_unit][unit];
        }
        dense[unit] = value > 0.0f ? value : 0.0f;
    }

    for (size_t output = 0; output < LSTM_INFERENCE_OUTPUTS; ++output)
    {
        float value = s_output_bias[output];
        for (size_t unit = 0; unit < HRC_LSTM_UNITS; ++unit)
        {
            value += dense[unit] * s_output_kernel[unit][output];
        }
        s_latest.distance_m[output] = value * s_target_std + s_target_mean;
        if (!isfinite(s_latest.distance_m[output]))
        {
            return false;
        }
    }
    return true;
}

static void lstm_update_threshold_decision(void)
{
    s_latest.threshold_m = s_threshold_m;
    s_latest.has_predicted_violation = false;
    s_latest.predicted_violation_ms = 0;
    if (s_latest.status != LSTM_INFERENCE_STATUS_OK)
    {
        s_latest.early_warning = false;
        return;
    }

    for (size_t i = 0; i < LSTM_INFERENCE_OUTPUTS; ++i)
    {
        if (s_latest.distance_m[i] <= s_threshold_m)
        {
            s_latest.has_predicted_violation = true;
            s_latest.predicted_violation_ms = (uint16_t)((i + 1u) * LSTM_INFERENCE_HORIZON_STEP_MS);
            break;
        }
    }
    s_latest.early_warning = s_distance[LSTM_INFERENCE_WINDOW_SIZE - 1u] > s_threshold_m &&
                             s_latest.has_predicted_violation;
}

void lstm_inference_init(void)
{
    lstm_clear_window();
    memset(&s_latest, 0, sizeof(s_latest));
    s_latest.status = LSTM_INFERENCE_STATUS_WARMUP;
    s_latest.threshold_m = s_threshold_m;
}

lstm_inference_status_t lstm_inference_push(uint32_t sequence,
                                             int64_t monotonic_us,
                                             float distance_m,
                                             bool valid)
{
#if !CONFIG_HRC_LSTM_INFERENCE
    (void)sequence;
    (void)monotonic_us;
    (void)distance_m;
    (void)valid;
    s_latest.status = LSTM_INFERENCE_STATUS_MODEL_UNAVAILABLE;
    s_latest.sample_count = 0;
    lstm_clear_forecast();
    return s_latest.status;
#else
    if (!valid || !isfinite(distance_m) || distance_m < 0.0f ||
        distance_m > HRC_LSTM_MAX_DISTANCE_M)
    {
        lstm_clear_window();
        s_latest.status = LSTM_INFERENCE_STATUS_INVALID_WINDOW;
        s_latest.sample_count = 0;
        lstm_clear_forecast();
        s_latest.threshold_m = s_threshold_m;
        return s_latest.status;
    }

    if (s_has_last_sample && !lstm_is_contiguous(sequence, monotonic_us))
    {
        lstm_clear_window();
        /* Match backend semantics: keep the current valid sample as the first
         * entry of the new buffer, while reporting INVALID_WINDOW for this
         * sample. The following sample continues warmup from count=1. */
        lstm_shift_and_append(distance_m, 0.0f);
        s_has_last_sample = true;
        s_last_sequence = sequence;
        s_last_monotonic_us = monotonic_us;
        s_latest.status = LSTM_INFERENCE_STATUS_INVALID_WINDOW;
        s_latest.sample_count = s_sample_count;
        lstm_clear_forecast();
        s_latest.threshold_m = s_threshold_m;
        return s_latest.status;
    }

    const float delta_m = s_has_last_sample ? distance_m - s_distance[s_sample_count - 1u] : 0.0f;
    lstm_shift_and_append(distance_m, delta_m);
    s_has_last_sample = true;
    s_last_sequence = sequence;
    s_last_monotonic_us = monotonic_us;
    s_latest.sample_count = s_sample_count;
    s_latest.threshold_m = s_threshold_m;
    lstm_clear_forecast();

    if (s_sample_count < LSTM_INFERENCE_WINDOW_SIZE)
    {
        s_latest.status = LSTM_INFERENCE_STATUS_WARMUP;
        return s_latest.status;
    }

    if (!lstm_run_model())
    {
        s_latest.status = LSTM_INFERENCE_STATUS_FAULT;
        return s_latest.status;
    }

    s_latest.status = LSTM_INFERENCE_STATUS_OK;
    lstm_update_threshold_decision();
    return s_latest.status;
#endif
}

lstm_inference_status_t lstm_inference_status(void)
{
    return s_latest.status;
}

const lstm_inference_result_t *lstm_inference_latest(void)
{
    return &s_latest;
}

const char *lstm_inference_status_name(lstm_inference_status_t status)
{
    switch (status)
    {
    case LSTM_INFERENCE_STATUS_WARMUP:
        return "WARMUP";
    case LSTM_INFERENCE_STATUS_OK:
        return "OK";
    case LSTM_INFERENCE_STATUS_INVALID_WINDOW:
        return "INVALID_WINDOW";
    case LSTM_INFERENCE_STATUS_MODEL_UNAVAILABLE:
        return "MODEL_UNAVAILABLE";
    case LSTM_INFERENCE_STATUS_FAULT:
        return "FAULT";
    default:
        return "UNKNOWN";
    }
}

bool lstm_inference_set_threshold(float threshold_m)
{
    if (!isfinite(threshold_m) || threshold_m < 0.0f || threshold_m > HRC_LSTM_MAX_DISTANCE_M)
    {
        return false;
    }
    s_threshold_m = threshold_m;
    s_latest.threshold_m = threshold_m;
    lstm_update_threshold_decision();
    return true;
}

float lstm_inference_threshold(void)
{
    return s_threshold_m;
}
